// SENT_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module SENT_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_tx_en,
  input logic  c_cfg_crc_legacy,
  input logic  c_cfg_rx_pause,
  input logic  c_cfg_rx_cal_check,
  input logic [11:0] c_cfg_tx_tick_clks,
  input logic [3:0] c_cfg_tx_low_ticks,
  input logic [2:0] c_cfg_tx_nibbles,
  input logic [1:0] c_cfg_tx_pause_mode,
  input logic [10:0] c_cfg_tx_pause,
  input logic [3:0] c_tx_status,
  input logic [23:0] c_tx_data,
  input logic [7:0] c_ser_tx_id,
  input logic [15:0] c_ser_tx_data,
  input logic  c_ser_tx_enh,
  input logic  c_ser_tx_cfg,
  input logic  c_ser_tx_start,
  input logic [11:0] c_cfg_rx_tick_clks,
  input logic [2:0] c_cfg_rx_nibbles,
  input logic [3:0] c_cfg_rx_filt,
  input logic  c_ser_tx_busy,
  input logic [3:0] c_rx_status,
  input logic [23:0] c_rx_data,
  input logic [18:0] c_rx_cal_clks,
  input logic  c_ser_rx_enh,
  input logic  c_ser_rx_cfg,
  input logic [7:0] c_ser_rx_id,
  input logic [15:0] c_ser_rx_data,
  input logic  c_rx_valid,
  input logic  c_ser_rx_valid,
  input logic  c_tx_frame_start,
  input logic  c_ser_tx_done,
  input logic  c_rx_err_nibble,
  input logic  c_rx_err_low,
  input logic  c_rx_err_crc,
  input logic  c_rx_err_pause,
  input logic  c_rx_err_sync,
  input logic  c_rx_err_cal,
  input logic  c_ser_rx_err_crc
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 16;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:15];          // model of every stored word
  logic [12:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_RX;          // full / valid pulse / available
  logic m_state_SER_RX;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_tx_frame_start) m_set[0] = 1'b1;
    if (c_ser_tx_done) m_set[1] = 1'b1;
    if (c_rx_err_nibble) m_set[2] = 1'b1;
    if (c_rx_err_low) m_set[3] = 1'b1;
    if (c_rx_err_crc) m_set[4] = 1'b1;
    if (c_rx_err_pause) m_set[5] = 1'b1;
    if (c_rx_err_sync) m_set[6] = 1'b1;
    if (c_rx_err_cal) m_set[7] = 1'b1;
    if (c_ser_rx_err_crc) m_set[8] = 1'b1;
    if (c_rx_valid && !m_state_RX) m_set[9] = 1'b1;
    if (c_rx_valid && m_state_RX && (m_rd && m_map && m_idx == 14)) m_set[9] = 1'b1;
    if (c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 14)) m_set[10] = 1'b1;
    if (c_ser_rx_valid && !m_state_SER_RX) m_set[11] = 1'b1;
    if (c_ser_rx_valid && m_state_SER_RX && (m_rd && m_map && m_idx == 15)) m_set[11] = 1'b1;
    if (c_ser_rx_valid && m_state_SER_RX && !(m_rd && m_map && m_idx == 15)) m_set[12] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h65096;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h16096;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_RX <= 0;
      m_state_SER_RX <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 10) ? PWDATA & m_be & 32'h1 : 0;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFF;
      if (c_rx_valid && (!m_state_RX || (m_rd && m_map && m_idx == 14))) begin
        m_w[13] <= (32'(c_rx_status[3:0]) << 0) | (32'(c_rx_data[23:0]) << 4);
        m_w[14] <= (32'(c_rx_cal_clks[18:0]) << 0);
        m_state_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 14)) m_state_RX <= 0;
      if (c_ser_rx_valid && (!m_state_SER_RX || (m_rd && m_map && m_idx == 15))) begin
        m_w[15] <= (32'(c_ser_rx_enh) << 0) | (32'(c_ser_rx_cfg) << 1) | (32'(c_ser_rx_id[7:0]) << 2) | (32'(c_ser_rx_data[15:0]) << 10);
        m_state_SER_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 15)) m_state_SER_RX <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h4A320100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_SER_RX, m_state_RX});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return 0;
      11: return m_w[11];
      12: return (32'(c_ser_tx_busy) << 0);
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][12:0] & m_w[2][12:0]))
  `SVA_INV(a_core_tx_en, c_tx_en == m_w[5][0:0])
  `SVA_INV(a_core_cfg_crc_legacy, c_cfg_crc_legacy == m_w[5][1:1])
  `SVA_INV(a_core_cfg_rx_pause, c_cfg_rx_pause == m_w[5][2:2])
  `SVA_INV(a_core_cfg_rx_cal_check, c_cfg_rx_cal_check == m_w[5][3:3])
  `SVA_INV(a_core_cfg_tx_tick_clks, c_cfg_tx_tick_clks == m_w[6][11:0])
  `SVA_INV(a_core_cfg_tx_low_ticks, c_cfg_tx_low_ticks == m_w[6][15:12])
  `SVA_INV(a_core_cfg_tx_nibbles, c_cfg_tx_nibbles == m_w[6][18:16])
  `SVA_INV(a_core_cfg_tx_pause_mode, c_cfg_tx_pause_mode == m_w[6][20:19])
  `SVA_INV(a_core_cfg_tx_pause, c_cfg_tx_pause == m_w[7][10:0])
  `SVA_INV(a_core_tx_status, c_tx_status == m_w[8][3:0])
  `SVA_INV(a_core_tx_data, c_tx_data == m_w[8][27:4])
  `SVA_INV(a_core_ser_tx_id, c_ser_tx_id == m_w[9][7:0])
  `SVA_INV(a_core_ser_tx_data, c_ser_tx_data == m_w[9][23:8])
  `SVA_INV(a_core_ser_tx_enh, c_ser_tx_enh == m_w[9][24:24])
  `SVA_INV(a_core_ser_tx_cfg, c_ser_tx_cfg == m_w[9][25:25])
  `SVA_INV(a_core_ser_tx_start, c_ser_tx_start == m_pulse_CMD[0])
  `SVA_INV(a_core_cfg_rx_tick_clks, c_cfg_rx_tick_clks == m_w[11][11:0])
  `SVA_INV(a_core_cfg_rx_nibbles, c_cfg_rx_nibbles == m_w[11][14:12])
  `SVA_INV(a_core_cfg_rx_filt, c_cfg_rx_filt == m_w[11][18:15])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_tx_en == 1'h0 && c_cfg_crc_legacy == 1'h0 && c_cfg_rx_pause == 1'h0 && c_cfg_rx_cal_check == 1'h0 && c_cfg_tx_tick_clks == 12'h96 && c_cfg_tx_low_ticks == 4'h5 && c_cfg_tx_nibbles == 3'h6 && c_cfg_tx_pause_mode == 2'h0 && c_cfg_tx_pause == 11'h0 && c_tx_status == 4'h0 && c_tx_data == 24'h0 && c_ser_tx_id == 8'h0 && c_ser_tx_data == 16'h0 && c_ser_tx_enh == 1'h0 && c_ser_tx_cfg == 1'h0 && c_ser_tx_start == 1'h0 && c_cfg_rx_tick_clks == 12'h96 && c_cfg_rx_nibbles == 3'h6 && c_cfg_rx_filt == 4'h2)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_TX_CFG, m_rd && m_map && m_idx == 6)
  `FC(wr_TX_CFG, m_wr && m_map && m_idx == 6)
  `FC(rd_TX_PAUSE, m_rd && m_map && m_idx == 7)
  `FC(wr_TX_PAUSE, m_wr && m_map && m_idx == 7)
  `FC(rd_TX_FRAME, m_rd && m_map && m_idx == 8)
  `FC(wr_TX_FRAME, m_wr && m_map && m_idx == 8)
  `FC(rd_SER_TX, m_rd && m_map && m_idx == 9)
  `FC(wr_SER_TX, m_wr && m_map && m_idx == 9)
  `FC(rd_CMD, m_rd && m_map && m_idx == 10)
  `FC(wr_CMD, m_wr && m_map && m_idx == 10)
  `FC(rd_RX_CFG, m_rd && m_map && m_idx == 11)
  `FC(wr_RX_CFG, m_wr && m_map && m_idx == 11)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 12)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 12)
  `FC(rd_RX0, m_rd && m_map && m_idx == 13)
  `FC(wr_RX0, m_wr && m_map && m_idx == 13)
  `FC(rd_RX1, m_rd && m_map && m_idx == 14)
  `FC(wr_RX1, m_wr && m_map && m_idx == 14)
  `FC(rd_SER_RX, m_rd && m_map && m_idx == 15)
  `FC(wr_SER_RX, m_wr && m_map && m_idx == 15)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_TX_FRAME_set, m_set[0])
  `FC(irq_TX_FRAME_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_TX_FRAME_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_TX_FRAME_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_SER_TX_DONE_set, m_set[1])
  `FC(irq_SER_TX_DONE_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_SER_TX_DONE_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_SER_TX_DONE_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ERR_NIBBLE_set, m_set[2])
  `FC(irq_ERR_NIBBLE_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ERR_NIBBLE_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ERR_NIBBLE_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_LOW_set, m_set[3])
  `FC(irq_ERR_LOW_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_LOW_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_LOW_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ERR_CRC_set, m_set[4])
  `FC(irq_ERR_CRC_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ERR_CRC_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ERR_CRC_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_ERR_PAUSE_set, m_set[5])
  `FC(irq_ERR_PAUSE_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_ERR_PAUSE_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_ERR_PAUSE_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_ERR_SYNC_set, m_set[6])
  `FC(irq_ERR_SYNC_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_ERR_SYNC_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_ERR_SYNC_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_ERR_CAL_set, m_set[7])
  `FC(irq_ERR_CAL_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_ERR_CAL_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_ERR_CAL_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_SER_CRC_set, m_set[8])
  `FC(irq_SER_CRC_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_SER_CRC_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_SER_CRC_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(irq_RX_AVAIL_set, m_set[9])
  `FC(irq_RX_AVAIL_cleared, m_w[1][9] && m_wr && m_map && m_idx == 1 && PWDATA[9] && PSTRB[1])
  `FC(irq_RX_AVAIL_masked, m_w[1][9] && !m_w[2][9])
  `FC(irq_RX_AVAIL_drives_pin, m_w[1][9] && m_w[2][9] && irq)
  `FC(irq_RX_OVF_set, m_set[10])
  `FC(irq_RX_OVF_cleared, m_w[1][10] && m_wr && m_map && m_idx == 1 && PWDATA[10] && PSTRB[1])
  `FC(irq_RX_OVF_masked, m_w[1][10] && !m_w[2][10])
  `FC(irq_RX_OVF_drives_pin, m_w[1][10] && m_w[2][10] && irq)
  `FC(irq_SER_RX_AVAIL_set, m_set[11])
  `FC(irq_SER_RX_AVAIL_cleared, m_w[1][11] && m_wr && m_map && m_idx == 1 && PWDATA[11] && PSTRB[1])
  `FC(irq_SER_RX_AVAIL_masked, m_w[1][11] && !m_w[2][11])
  `FC(irq_SER_RX_AVAIL_drives_pin, m_w[1][11] && m_w[2][11] && irq)
  `FC(irq_SER_RX_OVF_set, m_set[12])
  `FC(irq_SER_RX_OVF_cleared, m_w[1][12] && m_wr && m_map && m_idx == 1 && PWDATA[12] && PSTRB[1])
  `FC(irq_SER_RX_OVF_masked, m_w[1][12] && !m_w[2][12])
  `FC(irq_SER_RX_OVF_drives_pin, m_w[1][12] && m_w[2][12] && irq)
  `FC(cmd_ser_tx_start, m_pulse_CMD[0])
  `FC(RX_capture, c_rx_valid && !m_state_RX)
  `FC(RX_overflow, c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 14))
  `FC(RX_pop, m_rd && m_map && m_idx == 14 && m_state_RX)
  `FC(RX_read_empty, m_rd && m_map && m_idx == 14 && !m_state_RX)
  `FC(RX_pop_and_capture, c_rx_valid && m_state_RX && m_rd && m_map && m_idx == 14)
  `FC(SER_RX_capture, c_ser_rx_valid && !m_state_SER_RX)
  `FC(SER_RX_overflow, c_ser_rx_valid && m_state_SER_RX && !(m_rd && m_map && m_idx == 15))
  `FC(SER_RX_pop, m_rd && m_map && m_idx == 15 && m_state_SER_RX)
  `FC(SER_RX_read_empty, m_rd && m_map && m_idx == 15 && !m_state_SER_RX)
  `FC(SER_RX_pop_and_capture, c_ser_rx_valid && m_state_SER_RX && m_rd && m_map && m_idx == 15)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind SENT_apb SENT_apb_sva u_apb_sva (.*);
